// PORT: `T: Hash` values are hashed by small helpers that make the std `Hash` impl's calls
// (`Hash for u64` = `write_u64`, `Hash for &str` = `write_str`, `Hash for [i32]` =
// `write_length_prefix` + one `write` of the elements' native-endian bytes, tuples field by field).
// The `#[cfg(target_arch = "arm"/"x86")]` variants of `test_hash_usize` are skipped (64-bit host).
import { expect, test } from "bun:test";
