import type { Hasher } from "../stable_hasher.ts";

type Hash = (state: Hasher) => void;

// Hash just the bytes of the slice, without length prefix
// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:10 hash
function Bytes(b: Uint8Array): Hash {
  return (state) => {
    for (const byte of b) {
      state.write_u8(byte);
    }
  };
}

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:17 hash_with
function hash_with(st: SipHasher128, x: Hash): SipHasher128Hash {
  x(st);
  return st.finish();
}

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:22 hash
function hash(x: Hash): SipHasher128Hash {
  return hash_with(SipHasher128.new_with_keys(0n, 0n), x);
}

const u64_: (v: bigint) => Hash = (v) => (s) => s.write_u64(v);
const u32_: (v: number) => Hash = (v) => (s) => s.write_u32(v);
const usize_: (v: number) => Hash = (v) => (s) => s.write_usize(v);
const str_: (v: string) => Hash = (v) => (s) => s.write_str(utf8(v));
const slice_i32: (v: number[]) => Hash = (v) => (s) => {
  s.write_length_prefix(v.length);
  const b = new Uint8Array(4 * v.length);
  const dv = new DataView(b.buffer);
  v.forEach((x, i) => dv.setInt32(4 * i, x, true));
  s.write(b);
};
const tuple: (...xs: Hash[]) => Hash = (...xs) => (s) => {
  for (const x of xs) x(s);
};
const eq = SipHasher128Hash_eq;

