// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:95 test_siphash_1_3_test_vector
test("test_siphash_1_3_test_vector", () => {
  const k0 = 0x07_06_05_04_03_02_01_00n;
  const k1 = 0x0f_0e_0d_0c_0b_0a_09_08n;

  const input: number[] = [];

  for (const [i, v] of TEST_VECTOR.entries()) {
    const out = hash_with(SipHasher128.new_with_keys(k0, k1), Bytes(Uint8Array.from(input)));
    const le = (o: number) => v.slice(o, o + 8).reduceRight((acc, b) => (acc << 8n) | BigInt(b), 0n);
    const expected: [bigint, bigint] = [le(0), le(8)];

    expect(out._0).toEqual(expected);
    input.push(i);
  }
});

