// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:137 test_hash_usize
test("test_hash_usize (64-bit host)", () => {
  // PORT: `#[cfg(target_arch = "x86_64")]`; the same holds on every 64-bit host (aarch64 here).
  const val = 0xdeadbeef_deadbeefn;
  // `val as usize` does not fit a JS number: hash its bytes with write_usize's split (lo, hi).
  expect(eq(hash(u64_(val)), hash((s) => (s as SipHasher128).short_write(8, 0xdeadbeef | 0, 0xdeadbeef | 0)))).toBe(true);
  expect(eq(hash(usize_(0xdeadbeef_dead)), hash(u64_(0xdeadbeef_deadn)))).toBe(true);
  expect(!eq(hash(u32_(Number(val & 0xffffffffn))), hash(u64_(val)))).toBe(true);
});
