// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:159 test_hash_no_bytes_dropped_64
test("test_hash_no_bytes_dropped_64", () => {
  const val = 0xdeadbeef_deadbeefn;

  // crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:171 zero_byte
  function zero_byte(val: bigint, byte: number): bigint {
    expect(byte < 8).toBe(true);
    return val & ~(0xffn << BigInt(byte * 8));
  }

  for (let b = 0; b < 8; b++) expect(!eq(hash(u64_(val)), hash(u64_(zero_byte(val, b))))).toBe(true);
});

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:178 test_hash_no_bytes_dropped_32
test("test_hash_no_bytes_dropped_32", () => {
  const val = 0xdeadbeef;

  // crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:186 zero_byte
  function zero_byte(val: number, byte: number): number {
    expect(byte < 4).toBe(true);
    return (val & ~(0xff << (byte * 8))) >>> 0;
  }

  for (let b = 0; b < 4; b++) expect(!eq(hash(u32_(val)), hash(u32_(zero_byte(val, b))))).toBe(true);
});

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:193 test_hash_no_concat_alias
test("test_hash_no_concat_alias", () => {
  const s = tuple(str_("aa"), str_("bb"));
  const t = tuple(str_("aabb"), str_(""));
  const u = tuple(str_("a"), str_("abb"));

  expect(!eq(hash(s), hash(t)) && !eq(hash(s), hash(u))).toBe(true);

  const uu = [1, 0, 0, 0];
  const v = tuple(slice_i32(uu.slice(0, 1)), slice_i32(uu.slice(1, 3)), slice_i32(uu.slice(3)));
  const w = tuple(slice_i32(uu), slice_i32(uu.slice(4, 4)), slice_i32(uu.slice(4, 4)));

  expect(!eq(hash(v), hash(w))).toBe(true);
});

// `x.to_ne_bytes()` of an integer of `size` bytes (little-endian host).
function ne_bytes(x: bigint, size: number): Uint8Array {
  let v = BigInt.asUintN(size * 8, x);
  const out = new Uint8Array(size);
  for (let k = 0; k < size; k++) {
    out[k] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:210 test_short_write_works
test("test_short_write_works", () => {
  const test_u8 = 0xff;
  const test_u16 = 0x1122;
  const test_u32 = 0x22334455;
  const test_u64 = 0x33445566_778899aan;
  const test_u128 = 0x11223344_55667788_99aabbcc_ddeeff77n;
  const test_usize = 0xd0c0b0a0;

  const test_i8 = -1;
  const test_i16 = -2;
  const test_i32 = -3;
  const test_i64 = -4n;
  const test_i128 = -5n;
  const test_isize = -6;

  const h1 = SipHasher128.new_with_keys(0n, 0n);
  h1.write(utf8("bytes"));
  h1.write(utf8("string"));
  h1.write_u8(test_u8);
  h1.write_u16(test_u16);
  h1.write_u32(test_u32);
  h1.write_u64(test_u64);
  h1.write_u128(test_u128);
  h1.write_usize(test_usize);
  h1.write_i8(test_i8);
  h1.write_i16(test_i16);
  h1.write_i32(test_i32);
  h1.write_i64(test_i64);
  h1.write_i128(test_i128);
  h1.write_isize(test_isize);

  const h2 = SipHasher128.new_with_keys(0n, 0n);
  h2.write(utf8("bytes"));
  h2.write(utf8("string"));
  h2.write(ne_bytes(BigInt(test_u8), 1));
  h2.write(ne_bytes(BigInt(test_u16), 2));
  h2.write(ne_bytes(BigInt(test_u32), 4));
  h2.write(ne_bytes(test_u64, 8));
  h2.write(ne_bytes(test_u128, 16));
  h2.write(ne_bytes(BigInt(test_usize), 8));
  h2.write(ne_bytes(BigInt(test_i8), 1));
  h2.write(ne_bytes(BigInt(test_i16), 2));
  h2.write(ne_bytes(BigInt(test_i32), 4));
  h2.write(ne_bytes(test_i64, 8));
  h2.write(ne_bytes(test_i128, 16));
  h2.write(ne_bytes(BigInt(test_isize), 8));

  const h1_hash = h1.finish();
  const h2_hash = h2.finish();

  expect(h1_hash).toEqual(h2_hash);
});

// crate: rustc-stable-hash-0.1.2/src/sip128/tests.rs:292 test_fill_buffer
